// Applies the SQL migrations in ../drizzle (generated by drizzle-kit) after
// making sure the extensions exist. Run: pnpm db:migrate
import { fileURLToPath } from "node:url";
import { migrate } from "drizzle-orm/postgres-js/migrator";
import { loadConfig } from "@miniasys/core";
import { connect, type Database } from "./index.ts";

export async function runMigrations(database: Database): Promise<void> {
  await database.sql`CREATE EXTENSION IF NOT EXISTS vector`;
  await database.sql`CREATE EXTENSION IF NOT EXISTS pgcrypto`;
  await migrate(database.db, { migrationsFolder: fileURLToPath(new URL("../drizzle", import.meta.url)) });
}

if (import.meta.url === `file://${process.argv[1]}`) {
  const database = connect(loadConfig().databaseUrl, 1);
  runMigrations(database)
    .then(() => console.log("migrations applied"))
    .catch((e) => {
      console.error(e);
      process.exitCode = 1;
    })
    .finally(() => database.close());
}
